"""Shared gRPC channel options for source producer/consumer connections."""

from __future__ import annotations

# Keepalive follows gRPC guidance: avoid sub-minute PINGs and do not ping
# without active calls. See https://grpc.io/docs/guides/keepalive/
GRPC_CHANNEL_OPTIONS = (
    ("grpc.keepalive_time_ms", 300_000),
    ("grpc.keepalive_timeout_ms", 20_000),
    ("grpc.keepalive_permit_without_calls", 0),
)
